-- Generated by scripts/seed.mts. Do not edit by hand.
-- Run in the Supabase SQL editor as the postgres role.

set local role postgres;

insert into public.questions (id, subject, domain, skill, difficulty, type, stimulus, prompt, choices, answer, explanation)
select id, subject, domain, skill, difficulty, type, stimulus, prompt, choices, answer, explanation
from jsonb_to_recordset($seed$[{"id":"en-wic-01","subject":"english","domain":"Craft and Structure","skill":"Words in Context","difficulty":"easy","type":"mcq","stimulus":[{"type":"text","text":"The marine biologist's field notes were remarkably ___: every entry recorded the date, the water temperature, and the exact coordinates of each sighting."}],"prompt":"Which choice completes the text with the most logical and precise word or phrase?","choices":["careless","meticulous","brief","speculative"],"answer":{"choice":"B"},"explanation":"The colon introduces evidence of extreme care and precision (date, temperature, exact coordinates). \"Meticulous\" means showing great attention to detail, so it fits. \"Careless\" and \"speculative\" contradict the detail, and \"brief\" doesn't match notes that record so much."},{"id":"en-wic-02","subject":"english","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Although the novelist's early work was dismissed by critics as derivative, her later books were praised for their ___, introducing narrative techniques that other writers soon began to imitate."}],"prompt":"Which choice completes the text with the most logical and precise word or phrase?","choices":["originality","familiarity","length","restraint"],"answer":{"choice":"A"},"explanation":"\"Although\" signals a contrast with \"derivative\" (copied from others). Books that introduce techniques others imitate show originality. \"Familiarity\" repeats the criticism, and \"length\" and \"restraint\" aren't supported by the text."},{"id":"en-wic-03","subject":"english","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"In 1856, eighteen-year-old chemist William Perkin was trying to synthesize the drug quinine when he ___ produced mauveine, the first synthetic dye; he had not set out to create a dye at all."}],"prompt":"Which choice completes the text with the most logical and precise word or phrase?","choices":["deliberately","reluctantly","accidentally","gradually"],"answer":{"choice":"C"},"explanation":"The text says Perkin \"had not set out to create a dye at all,\" so the dye was produced by accident. \"Deliberately\" contradicts this, and nothing suggests he was reluctant or that the discovery was gradual."},{"id":"en-wic-04","subject":"english","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Urban ecologist Priya Raman argues that when budgets tighten, city parks are too often treated as ___ amenities—pleasant but expendable—even though her research shows that parks substantially lower summer temperatures in surrounding neighborhoods."}],"prompt":"Which choice completes the text with the most logical and precise word or phrase?","choices":["essential","ancillary","controversial","innovative"],"answer":{"choice":"B"},"explanation":"The phrase \"pleasant but expendable\" defines the blank: something secondary or supplementary. \"Ancillary\" means providing support but not essential. \"Essential\" is the opposite of the officials' view that Raman criticizes."},{"id":"en-wic-05","subject":"english","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"The historian's account does not ___ the role that merchants played in the city's growth; rather, it argues that their influence has been overstated by earlier scholars, who relied almost exclusively on the merchants' own letters."}],"prompt":"Which choice completes the text with the most logical and precise word or phrase?","choices":["exaggerate","dismiss","document","celebrate"],"answer":{"choice":"B"},"explanation":"\"Rather\" contrasts what the account does not do with what it does: it says the merchants' influence was overstated, not that it was nonexistent. So the account does not dismiss their role entirely. \"Exaggerate\" would contradict the argument that others overstated it."},{"id":"en-wic-06","subject":"english","domain":"Craft and Structure","skill":"Words in Context","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Before approving the bridge design, the review board asked an independent engineer to check every calculation. Her report concluded that the plan was *sound*: the structure could safely carry more than twice the expected traffic load."}],"prompt":"As used in the text, what does the word \"sound\" most nearly mean?","choices":["noisy","reliable","complete","deep"],"answer":{"choice":"B"},"explanation":"The report explains that the structure could safely carry more than twice the expected load, which shows the plan is dependable. In this context \"sound\" means reliable or well founded."},{"id":"en-wic-07","subject":"english","domain":"Craft and Structure","skill":"Words in Context","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Physicist Lise Meitner's role in the discovery of nuclear fission was long ___: although she helped provide the first theoretical explanation of the key experiment, the 1944 Nobel Prize in Chemistry was awarded to her collaborator Otto Hahn alone."}],"prompt":"Which choice completes the text with the most logical and precise word or phrase?","choices":["overlooked","exaggerated","disputed","publicized"],"answer":{"choice":"A"},"explanation":"The colon introduces evidence that Meitner didn't receive credit: the prize went to Hahn alone. Her role was therefore overlooked. Nothing suggests it was exaggerated or widely publicized."},{"id":"en-tsp-01","subject":"english","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Octopuses have long puzzled biologists. With a nervous system spread largely through their arms, they can solve mazes, unscrew jar lids, and recognize individual human faces. Yet octopuses live only one to two years and receive no instruction from their parents, which die shortly after the eggs hatch. Researchers are therefore trying to understand how such complex abilities evolved in an animal with so little time to use them."}],"prompt":"Which choice best describes the overall structure of the text?","choices":["It describes impressive abilities of octopuses, then presents features of their lives that make those abilities puzzling.","It presents a theory about octopus intelligence and then offers evidence that disproves it.","It compares octopuses with other animals and concludes that octopuses are the most intelligent.","It explains how octopuses learn from their parents and then describes an experiment."],"answer":{"choice":"A"},"explanation":"The text first lists abilities (mazes, jars, faces), then uses \"Yet\" to introduce the short lifespan and lack of parental teaching, which make those abilities puzzling. No theory is disproved, no comparison is made, and the text says octopuses do not learn from parents."},{"id":"en-tsp-02","subject":"english","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"easy","type":"mcq","stimulus":[{"type":"text","text":"In 2011, Mexican American artist Judith Baca began restoring sections of *The Great Wall of Los Angeles*, a half-mile-long mural she first designed in 1974. The mural, painted along a flood-control channel, depicts California's history from the perspective of communities often left out of textbooks. The restoration, carried out with teams of young local artists, was meant not only to repair fading paint but also to pass the skills of mural making on to a new generation."}],"prompt":"Which choice best states the main purpose of the text?","choices":["To argue that murals should not be painted outdoors","To describe a mural and explain the goals of an effort to restore it","To compare Baca's mural with other murals in Los Angeles","To criticize textbooks for leaving out parts of California's history"],"answer":{"choice":"B"},"explanation":"The text introduces the mural, describes what it depicts, and explains that the restoration aimed both to repair it and to teach young artists. The other choices focus on details the text doesn't develop."},{"id":"en-tsp-03","subject":"english","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Many people assume that deserts are silent places. ++In fact, the sand dunes of the Sahara and several other deserts can produce a low, droning hum that is audible from kilometers away.++ Scientists have found that the sound occurs when sand grains of a particular size slide down the steep face of a dune in a synchronized avalanche. The pitch of the hum depends on the size of the grains rather than on the shape of the dune."}],"prompt":"Which choice best describes the function of the underlined sentence in the text as a whole?","choices":["It presents a hypothesis that the scientists mentioned later reject.","It provides an example of how deserts differ from all other environments.","It introduces a phenomenon that challenges a common assumption and is explained in the rest of the text.","It summarizes the findings of the research described in the text."],"answer":{"choice":"C"},"explanation":"The underlined sentence contradicts the assumption that deserts are silent by introducing humming dunes, and the following sentences explain what causes the hum. It is not a rejected hypothesis or a summary."},{"id":"en-tsp-04","subject":"english","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"When automated teller machines (ATMs) spread in the 1970s and 1980s, some economists predicted that the number of bank tellers in the United States would fall sharply. Instead, the number of tellers grew over the following decades. Because ATMs lowered the cost of running a branch, banks opened many more branches, and tellers increasingly took on tasks such as advising customers—work that machines could not easily do."}],"prompt":"Which choice best states the main purpose of the text?","choices":["To argue that ATMs should eventually replace bank tellers","To describe how ATMs process transactions","To explain why economists study the banking industry","To show that a new technology affected employment differently than some had predicted"],"answer":{"choice":"D"},"explanation":"The text contrasts a prediction (tellers would disappear) with the outcome (tellers increased) and explains why. Its purpose is to show that the technology's effect on jobs differed from expectations."},{"id":"en-tsp-05","subject":"english","domain":"Craft and Structure","skill":"Text Structure and Purpose","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Sea turtles hatch on beaches at night and must reach the ocean quickly. For decades, researchers assumed that hatchlings found the water by following the sound of breaking waves. Experiments have since shown that hatchlings instead crawl toward the brightest horizon, which on an undeveloped beach is usually the open sea. This finding explains why artificial lights near beaches can lead hatchlings in the wrong direction."}],"prompt":"Which choice best describes the overall structure of the text?","choices":["It describes a problem facing sea turtles and proposes several possible solutions.","It presents an earlier assumption, describes findings that replaced it, and notes a consequence of those findings.","It compares the behavior of two species of sea turtles.","It argues that most research on sea turtles has been unreliable."],"answer":{"choice":"B"},"explanation":"The text states an old assumption (sound), replaces it with newer evidence (brightest horizon), and ends with an implication (artificial lights mislead hatchlings). No solutions or species comparisons are offered."},{"id":"en-ctc-01","subject":"english","domain":"Craft and Structure","skill":"Cross-Text Connections","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Many researchers have argued that dog domestication began when wolves scavenged near human camps. Over generations, the wolves least afraid of people were the ones that thrived near settlements, gradually becoming tamer and eventually dependent on humans.","title":"Text 1"},{"type":"text","text":"Geneticist Laila Morgan questions whether scavenging alone can explain domestication. Early human groups in cold regions, she notes, often had little surplus meat to leave behind. Morgan proposes instead that people actively captured and raised wolf pups, deliberately keeping the calmest animals.","title":"Text 2"}],"prompt":"Based on the texts, how would Morgan (Text 2) most likely respond to the explanation described in Text 1?","choices":["By agreeing that tamer wolves had an advantage but arguing that humans played a more deliberate role than the explanation suggests","By arguing that dogs were domesticated from an animal other than the wolf","By claiming that early humans did not live in cold regions","By insisting that tameness gave wolves no advantage near human settlements"],"answer":{"choice":"A"},"explanation":"Morgan still thinks calm animals were favored (people kept \"the calmest animals\"), but she argues humans chose them deliberately rather than wolves drifting toward camps on their own. She doesn't dispute that dogs came from wolves."},{"id":"en-ctc-02","subject":"english","domain":"Craft and Structure","skill":"Cross-Text Connections","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Four-day workweeks are often promoted as a way to improve employees' well-being. In a widely reported 2022 trial in the United Kingdom, most participating companies kept the shorter schedule after the trial ended, and employees reported lower levels of stress.","title":"Text 1"},{"type":"text","text":"Results from trials of shorter workweeks should be interpreted carefully. Companies chose to join the 2022 trial, so they may have been especially well suited to a shorter schedule. Organizations such as hospitals, which must operate around the clock, could face very different challenges.","title":"Text 2"}],"prompt":"Based on the texts, how would the author of Text 2 most likely characterize the findings described in Text 1?","choices":["As evidence that shorter workweeks increase stress","As inaccurate because companies misreported their results","As possibly not applicable to every type of organization","As proof that hospitals should adopt a four-day workweek"],"answer":{"choice":"C"},"explanation":"Text 2 points out that the participating companies volunteered and that round-the-clock organizations might differ, so the findings may not generalize. It doesn't claim the results were misreported or wrong."},{"id":"en-cid-01","subject":"english","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"easy","type":"mcq","stimulus":[{"type":"text","text":"Mara had lived in the city for eleven years, but each spring she still found herself drawn back to her grandmother's farm. She told her friends it was for the fresh air. The truth was harder to explain: only there, among the rows of pear trees her grandmother had planted, did she feel that the pieces of her life fit together."}],"prompt":"Which choice best states the main idea of the text?","choices":["Mara prefers living in the city to living in the countryside.","Mara's friends do not understand why she enjoys fresh air.","Mara plans to become a farmer like her grandmother.","Mara returns to the farm because it gives her a sense of belonging that is hard to put into words."],"answer":{"choice":"D"},"explanation":"The key sentence says the real reason is \"harder to explain\": the farm makes her feel that her life fits together. That is a sense of belonging. The text never says she plans to farm or compares city and country."},{"id":"en-cid-02","subject":"english","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Research by ecologist Tomás Herrera suggests that coffee farms that keep native trees growing among the coffee plants support far more bird species than farms that clear the trees. Some farmers worry that shade reduces coffee yields. Herrera found, however, that birds on shaded farms ate enough crop-damaging insects to offset much of the yield lost to shade."}],"prompt":"Which choice best states the main idea of the text?","choices":["Keeping shade trees on coffee farms can benefit both birds and farmers.","Coffee farmers should stop growing coffee in forested areas.","Birds are the main cause of damage to coffee crops.","Most of the world's coffee is grown without shade trees."],"answer":{"choice":"A"},"explanation":"Shaded farms support more bird species, and those birds eat insects that damage crops, offsetting yield losses. So shade trees help both birds and farmers. The birds protect crops rather than damage them."},{"id":"en-cid-03","subject":"english","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"The Voynich manuscript, a fifteenth-century book written in an unknown script, has resisted a century of decoding attempts. Some scholars have concluded that it is an elaborate hoax. Linguist Rhea Sato disagrees, pointing out that the frequency with which certain \"words\" appear in the manuscript follows the same statistical pattern found in natural languages—a pattern that a medieval forger would have had no reason to know about, let alone reproduce."}],"prompt":"According to the text, why does Sato doubt that the manuscript is a hoax?","choices":["The manuscript's script closely resembles a known medieval alphabet.","Many scholars have successfully translated portions of the manuscript.","Word patterns in the manuscript match those of natural languages in a way a forger would be unlikely to imitate.","The manuscript was written much more recently than scholars once believed."],"answer":{"choice":"C"},"explanation":"Sato's reasoning is that the word-frequency pattern matches natural languages, and a medieval forger wouldn't have known to reproduce it. The text says the script is unknown and hasn't been decoded."},{"id":"en-cid-04","subject":"english","domain":"Information and Ideas","skill":"Central Ideas and Details","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"In the 1930s, photographer Dorothea Lange traveled across the American West documenting families displaced by drought and economic hardship. Rather than photographing crowds, Lange usually focused on individuals, often waiting until her subjects grew comfortable with her presence. The resulting portraits, such as *Migrant Mother* (1936), gave audiences across the country a personal view of the era's hardships."}],"prompt":"Which choice best states the main idea of the text?","choices":["Lange preferred photographing large crowds to photographing individuals.","Lange's work was mostly unknown to audiences during the 1930s.","Lange's patient, close portraits of individuals helped audiences understand the hardships of the 1930s.","Lange stopped working as a photographer after 1936."],"answer":{"choice":"C"},"explanation":"The text emphasizes Lange's focus on individuals, her patience, and the portraits' effect on national audiences. Choice A contradicts the text, and B and D aren't supported."},{"id":"en-coe-01","subject":"english","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Biologist Anika Rhodes hypothesizes that honeybees learn to associate a particular color with a sugar reward more quickly in warm conditions than in cool conditions."}],"prompt":"Which finding, if true, would most directly support Rhodes's hypothesis?","choices":["Honeybees visited blue flowers more often than yellow flowers.","Bees trained at 28°C learned to link a color with sugar in fewer trials than bees trained at 18°C.","Bees kept in cool conditions produced more honey than bees kept in warm conditions.","Honeybees can detect ultraviolet light that humans cannot see."],"answer":{"choice":"B"},"explanation":"The hypothesis compares learning speed in warm versus cool conditions. Only choice B compares how quickly bees learned a color–sugar association at a warmer and a cooler temperature, with the warm group learning faster."},{"id":"en-coe-02","subject":"english","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"In the poem \"Night Harbor,\" the speaker presents the harbor as a place that offers both comfort and unease."}],"prompt":"Which quotation from \"Night Harbor\" most effectively illustrates the claim?","choices":["\"The boats return at dusk, one by one, / their hulls still bright with the afternoon.\"","\"The gulls have folded into sleep / along the long gray fingers of the pier.\"","\"Tomorrow the nets go out again at four; / tomorrow, the same salt, the same slow tide.\"","\"The lanterns hum their small and steady songs, / yet something in the black water waits.\""],"answer":{"choice":"D"},"explanation":"Choice D pairs a comforting image (lanterns' \"small and steady songs\") with an uneasy one (\"something in the black water waits\"), linked by \"yet.\" The other quotations each convey a single mood."},{"id":"en-coe-03","subject":"english","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Sociologist Marcus Bell claims that public libraries now serve as important community gathering places, not just as places to borrow books."}],"prompt":"Which finding, if true, would most directly support Bell's claim?","choices":["The number of books borrowed from public libraries fell over the past decade.","Libraries in large cities hold more books than libraries in small towns.","Most public libraries in the country were built before 1950.","A survey found that over half of library visitors came to attend events, use computers, or meet others rather than to borrow books."],"answer":{"choice":"D"},"explanation":"Bell's claim is that libraries function as community spaces. Evidence that most visitors come for events, computers, or meeting people directly supports it. Falling book loans alone doesn't show that libraries are gathering places."},{"id":"en-coq-01","subject":"english","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"medium","type":"mcq","stimulus":[{"type":"table","title":"Average Daily Recreational Screen Time (hours)","headers":["Age group","Weekdays","Weekends"],"rows":[["8–12 years","4.4","5.6"],["13–18 years","7.1","8.6"]]},{"type":"text","text":"A researcher studying young people's media habits noted that children and teenagers alike spend more time on screens on weekends than on weekdays. For example, ___"}],"prompt":"Which choice most effectively uses data from the table to complete the example?","choices":["teenagers averaged more screen time on weekdays than children ages 8–12 did.","children ages 8–12 averaged 5.6 hours of screen time on weekends.","teenagers averaged 7.1 hours on weekdays and 8.6 hours on weekends, while children ages 8–12 averaged 4.4 and 5.6 hours, respectively.","children ages 8–12 averaged more screen time on weekdays than teenagers did on weekends."],"answer":{"choice":"C"},"explanation":"The claim concerns both groups and compares weekends with weekdays. Choice C gives both values for both groups, showing weekend time is higher for each. Choice D is false (4.4 < 8.6), and A and B don't make the weekday–weekend comparison for both groups."},{"id":"en-coq-02","subject":"english","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"hard","type":"mcq","stimulus":[{"type":"figure","caption":"Seed Germination by Soil Type","figure":{"kind":"bar","yLabel":"Seeds germinated (%)","xLabel":"Soil type","y":[0,100,20],"bars":[{"label":"Sandy","value":42},{"label":"Loam","value":78},{"label":"Clay","value":55},{"label":"Loam + compost","value":91}]}},{"type":"text","text":"For a science fair project, a student hypothesized that adding compost to loam soil would increase the percentage of seeds that germinate compared with loam soil alone. The data in the graph ___"}],"prompt":"Which choice most effectively uses data from the graph to complete the statement?","choices":["support the hypothesis, because 91% of seeds germinated in loam with compost, compared with 78% in loam alone.","support the hypothesis, because more seeds germinated in clay soil than in sandy soil.","weaken the hypothesis, because only 42% of seeds germinated in sandy soil.","weaken the hypothesis, because 78% of seeds germinated in loam soil."],"answer":{"choice":"A"},"explanation":"The hypothesis compares loam + compost with loam alone. The graph shows 91% versus 78%, so the data support it. Clay and sandy soil are irrelevant to this comparison."},{"id":"en-coq-03","subject":"english","domain":"Information and Ideas","skill":"Command of Evidence","difficulty":"medium","type":"mcq","stimulus":[{"type":"table","title":"Riverton Bike-Share Trips (thousands per year)","headers":["Year","Electric bikes","Standard bikes"],"rows":[["2021","12","48"],["2022","25","46"],["2023","41","44"]]},{"type":"text","text":"Riverton's bike-share program added electric bikes in 2021. City planners noted that the electric bikes quickly grew in popularity while use of standard bikes stayed fairly stable. By 2023, ___"}],"prompt":"Which choice most effectively uses data from the table to complete the statement?","choices":["electric bikes accounted for 12 thousand trips.","standard bikes accounted for more than 48 thousand trips.","electric bike trips had fallen below 25 thousand.","electric bike trips had risen to 41 thousand, while standard bike trips were 44 thousand, down only slightly from 48 thousand in 2021."],"answer":{"choice":"D"},"explanation":"The statement describes two trends: electric bikes growing and standard bikes staying stable. Choice D shows both with accurate 2023 values. The other choices misstate the data."},{"id":"en-inf-01","subject":"english","domain":"Information and Ideas","skill":"Inferences","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"At a coastal site in present-day Peru, archaeologists found cotton fishing nets dating to about 5,000 years ago but no farming tools or stored grain from the same period. Because cotton must be cultivated, the nets suggest that ___"}],"prompt":"Which choice most logically completes the text?","choices":["the people at the site grew at least some crops, even though evidence of grain farming has not been found.","the people at the site did not rely on fishing for food.","cotton was not used to make nets until thousands of years later.","the site was abandoned before cotton was first cultivated."],"answer":{"choice":"A"},"explanation":"Since cotton must be cultivated, cotton nets imply that someone was growing a crop, even without grain or farming tools. The nets also show the people fished, contradicting choice B."},{"id":"en-inf-02","subject":"english","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Young male zebra finches normally learn their songs by imitating adult males. When researchers raised finches in isolation, the birds developed unusual, irregular songs. The researchers then had young birds learn from these isolated \"tutors,\" and had each new generation learn from the one before. Over several generations, the songs gradually became more like those of wild zebra finches. This finding suggests that ___"}],"prompt":"Which choice most logically completes the text?","choices":["zebra finches are unable to learn songs from other birds.","zebra finches have an inborn tendency that pushes their songs toward the typical wild form.","wild zebra finch songs change unpredictably from one generation to the next.","raising finches in isolation improves the quality of their songs."],"answer":{"choice":"B"},"explanation":"Even though each generation learned from birds with irregular songs, the songs drifted back toward the wild form. That suggests something innate guides song development. The birds clearly did learn from tutors, so A is wrong."},{"id":"en-inf-03","subject":"english","domain":"Information and Ideas","skill":"Inferences","difficulty":"easy","type":"mcq","stimulus":[{"type":"text","text":"Many popular houseplants originated on the floors of tropical forests, where they grew in the shade of much taller trees. As a result, many of these plants ___"}],"prompt":"Which choice most logically completes the text?","choices":["need direct sunlight for most of the day.","grow best in hot, dry desert conditions.","can thrive in the indirect light found inside most homes.","cannot survive indoors for more than a few weeks."],"answer":{"choice":"C"},"explanation":"Plants adapted to shade beneath tall trees are suited to low, indirect light, which is similar to the light inside homes. The other choices contradict their shady origins."},{"id":"en-inf-04","subject":"english","domain":"Information and Ideas","skill":"Inferences","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Many fig species can be pollinated by only one particular species of wasp, and those wasps can reproduce only inside the flowers of that fig species. On a remote island, botanists found a fig species that relies on such a partnership, but after a thorough survey they found no trace of its pollinating wasp. It can most reasonably be concluded that ___"}],"prompt":"Which choice most logically completes the text?","choices":["the pollinating wasps are thriving on the island.","fig trees on the island do not need to be pollinated to produce seeds.","the wasps have begun reproducing inside other plants on the island.","the figs on the island are not currently being pollinated by their usual wasp partner."],"answer":{"choice":"D"},"explanation":"If the fig relies on one wasp species and that wasp is absent from the island, the figs there cannot currently be pollinated by it. The text says the wasps reproduce only in that fig, which rules out C."},{"id":"en-bnd-01","subject":"english","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"easy","type":"mcq","stimulus":[{"type":"text","text":"The Atacama Desert in northern Chile is one of the driest places on ___ some of its weather stations have never recorded a single drop of rain."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["Earth, some","Earth; some","Earth some","Earth, and, some"],"answer":{"choice":"B"},"explanation":"Both parts are independent clauses. A semicolon correctly joins them. A comma alone creates a comma splice, no punctuation creates a run-on, and \"and,\" with an extra comma is incorrect."},{"id":"en-bnd-02","subject":"english","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Astronomer Vera Rubin's measurements of how fast stars orbit the centers of galaxies provided some of the strongest early evidence for ___ invisible form of matter that does not emit light."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["dark matter, an","dark matter. An","dark matter; an","dark matter an"],"answer":{"choice":"A"},"explanation":"\"An invisible form of matter...\" is an appositive that renames \"dark matter,\" so it should be set off with a comma. A period or semicolon would leave a fragment, and no punctuation fuses the appositive to the noun."},{"id":"en-bnd-03","subject":"english","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"In 1903, Maggie L. Walker became the first woman in the United States to charter a bank. The bank, the St. Luke Penny Savings ___ served Richmond's Black community for decades."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["Bank; which","Bank, which","Bank which","Bank. Which"],"answer":{"choice":"B"},"explanation":"The appositive \"the St. Luke Penny Savings Bank\" begins with a comma after \"The bank,\" so it must close with a comma too. A semicolon or period would break up the sentence, and without the comma the appositive isn't closed."},{"id":"en-bnd-04","subject":"english","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Coral reefs cover less than 1 percent of the ocean ___ they support roughly a quarter of all known marine species."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["floor yet","floor yet,","floor, yet,","floor, yet"],"answer":{"choice":"D"},"explanation":"Two independent clauses joined by the coordinating conjunction \"yet\" need a comma before the conjunction and no comma after it."},{"id":"en-bnd-05","subject":"english","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"The research team included three specialists: Amara Diallo, a marine ___ Kenji Ito, a statistician; and Sofia Reyes, a climate modeler."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["biologist,","biologist","biologist;","biologist:"],"answer":{"choice":"C"},"explanation":"The list items already contain commas (\"Amara Diallo, a marine biologist\"), so the items must be separated by semicolons, matching the semicolon after \"statistician.\""},{"id":"en-bnd-06","subject":"english","domain":"Standard English Conventions","skill":"Boundaries","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"The Mars rover Perseverance carried a small ___ named Ingenuity—that in 2021 became the first aircraft to make a powered, controlled flight on another planet."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["helicopter,","helicopter;","helicopter","helicopter—"],"answer":{"choice":"D"},"explanation":"The phrase \"named Ingenuity\" is a supplementary element closed by a dash, so it must open with a dash as well. Punctuation around an interrupting element must match."},{"id":"en-fss-01","subject":"english","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"easy","type":"mcq","stimulus":[{"type":"text","text":"The collection of antique maps in the museum's east wing ___ visitors from around the world each year."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["attract","attracts","are attracting","have attracted"],"answer":{"choice":"B"},"explanation":"The subject is the singular noun \"collection\" (not \"maps\"), so it needs the singular verb \"attracts.\" \"Each year\" also calls for the simple present."},{"id":"en-fss-02","subject":"english","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"After months of debate, the city council finally approved the new composting program. In a statement released the next morning, ___ announced that curbside collection would begin in March."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["they","it","them","their"],"answer":{"choice":"B"},"explanation":"The pronoun refers to \"the city council,\" a singular collective noun, so the singular subject pronoun \"it\" is correct."},{"id":"en-fss-03","subject":"english","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"By the time Tenzing Norgay and Edmund Hillary reached the summit of Mount Everest in 1953, other climbers ___ to reach it for more than thirty years."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["are trying","will have tried","had been trying","try"],"answer":{"choice":"C"},"explanation":"The attempts were ongoing before a past event (1953), so the past perfect progressive \"had been trying\" is required."},{"id":"en-fss-04","subject":"english","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Having studied the migration of monarch butterflies for over a decade, ___"}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["the monarchs' new route surprised Dr. Lin.","Dr. Lin was surprised by a change in the monarchs' route.","a change in the monarchs' route surprised Dr. Lin.","the surprise for Dr. Lin was a change in the monarchs' route."],"answer":{"choice":"B"},"explanation":"The introductory phrase describes someone who studied monarchs, so the subject right after the comma must be that person: Dr. Lin. Otherwise the modifier dangles."},{"id":"en-fss-05","subject":"english","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Cliff swallows return to the same colony each spring. The ___ nests, built from pellets of mud, can cling to a cliff face for many years."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["birds","bird's","birds'","birds's"],"answer":{"choice":"C"},"explanation":"The nests belong to many birds, so the plural possessive \"birds'\" is correct."},{"id":"en-fss-06","subject":"english","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Each of the paintings in the exhibition, which features artists from twelve countries, ___ a different interpretation of the theme of home."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["offer","have offered","offers","are offering"],"answer":{"choice":"C"},"explanation":"The subject is \"Each,\" which is singular. Ignore the intervening phrase \"of the paintings...\" and choose the singular verb \"offers.\""},{"id":"en-fss-07","subject":"english","domain":"Standard English Conventions","skill":"Form, Structure, and Sense","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Since it opened in 1897, the Library of Congress's Thomas Jefferson Building ___ millions of visitors with its elaborate murals, mosaics, and sculptures."}],"prompt":"Which choice completes the text so that it conforms to the conventions of Standard English?","choices":["has impressed","impress","impressing","will impress"],"answer":{"choice":"A"},"explanation":"\"Since it opened in 1897\" describes an action that began in the past and continues to the present, which calls for the present perfect \"has impressed.\" \"Impressing\" can't serve as the main verb."},{"id":"en-trn-01","subject":"english","domain":"Expression of Ideas","skill":"Transitions","difficulty":"easy","type":"mcq","stimulus":[{"type":"text","text":"Honeybees tell hive mates where to find food by performing a movement called the waggle dance. The angle of the dance indicates the food's direction relative to the sun. ___ the length of each waggle indicates how far away the food is."}],"prompt":"Which choice completes the text with the most logical transition?","choices":["However,","Meanwhile,","Instead,","Additionally,"],"answer":{"choice":"D"},"explanation":"The final sentence adds a second piece of information the dance conveys (distance) to the first (direction), so \"Additionally\" fits. There is no contrast or substitution."},{"id":"en-trn-02","subject":"english","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"In the early 1900s, electric cars were quieter, cleaner, and easier to start than gasoline cars. ___ they were soon overtaken in popularity by gasoline cars, which could travel much farther before needing to refuel."}],"prompt":"Which choice completes the text with the most logical transition?","choices":["Nevertheless,","Therefore,","For example,","Likewise,"],"answer":{"choice":"A"},"explanation":"Despite their advantages, electric cars lost out. \"Nevertheless\" signals this contrast with what came before."},{"id":"en-trn-03","subject":"english","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Mangrove forests protect coastlines by absorbing the energy of incoming waves. ___ areas with healthy mangroves often suffer less damage during storms than areas where mangroves have been cleared."}],"prompt":"Which choice completes the text with the most logical transition?","choices":["In contrast,","Nonetheless,","As a result,","Previously,"],"answer":{"choice":"C"},"explanation":"Less storm damage is a consequence of mangroves absorbing wave energy, so a cause-and-effect transition, \"As a result,\" is logical."},{"id":"en-trn-04","subject":"english","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"Well into the twentieth century, many astronomers believed that the Milky Way contained every star in the universe. In the 1920s, ___ Edwin Hubble showed that some faint, fuzzy patches in the night sky were entire galaxies lying far beyond our own."}],"prompt":"Which choice completes the text with the most logical transition?","choices":["however,","for instance,","similarly,","in other words,"],"answer":{"choice":"A"},"explanation":"Hubble's discovery overturned the earlier belief, so a contrasting transition, \"however,\" is needed."},{"id":"en-trn-05","subject":"english","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Tardigrades, tiny animals less than a millimeter long, can survive astonishing extremes. They have endured temperatures near absolute zero, intense radiation, and even the vacuum of space. ___ biologists study them to learn how living cells might be protected from damage."}],"prompt":"Which choice completes the text with the most logical transition?","choices":["Still,","Instead,","Consequently,","By contrast,"],"answer":{"choice":"C"},"explanation":"Scientists study tardigrades because of their extraordinary resilience. The last sentence is a result of the previous ones, so \"Consequently\" fits."},{"id":"en-trn-06","subject":"english","domain":"Expression of Ideas","skill":"Transitions","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"The Great Pacific Garbage Patch is often imagined as a floating island of trash. ___ most of its debris consists of tiny plastic particles suspended below the surface, making the patch nearly invisible from the deck of a ship."}],"prompt":"Which choice completes the text with the most logical transition?","choices":["Moreover,","In reality,","Likewise,","Thus,"],"answer":{"choice":"B"},"explanation":"The second sentence corrects the popular image described in the first, so \"In reality\" is the logical transition."},{"id":"en-trn-07","subject":"english","domain":"Expression of Ideas","skill":"Transitions","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"Many desert plants survive dry seasons by storing water in thick, fleshy leaves and stems. ___ others, such as the mesquite tree, send roots more than 50 meters underground to reach water deep below the surface."}],"prompt":"Which choice completes the text with the most logical transition?","choices":["Similarly,","Therefore,","In contrast,","For instance,"],"answer":{"choice":"C"},"explanation":"The second sentence describes a different survival strategy (deep roots rather than water storage), so the contrasting transition \"In contrast\" fits."},{"id":"en-rs-01","subject":"english","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","type":"mcq","stimulus":[{"type":"list","intro":"While researching a topic, a student has taken the following notes:","items":["The axolotl is a salamander native to lakes near Mexico City.","Unlike most salamanders, axolotls keep juvenile features, such as feathery external gills, throughout their lives.","Axolotls can regrow lost limbs, parts of the spinal cord, and even parts of the heart.","Scientists study axolotls to better understand how tissue regenerates."]}],"prompt":"The student wants to explain why scientists are interested in axolotls. Which choice most effectively uses relevant information from the notes to accomplish this goal?","choices":["The axolotl is a salamander native to lakes near Mexico City.","Because axolotls can regrow limbs and even parts of the heart, scientists study them to learn how tissue regenerates.","Axolotls keep feathery external gills throughout their lives.","Unlike most salamanders, axolotls keep their juvenile features as adults."],"answer":{"choice":"B"},"explanation":"Only choice B connects the axolotl's regenerative ability to scientists' reason for studying it."},{"id":"en-rs-02","subject":"english","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","type":"mcq","stimulus":[{"type":"list","intro":"While researching a topic, a student has taken the following notes:","items":["The Hubble Space Telescope launched in 1990.","Hubble observes mainly visible and ultraviolet light.","The James Webb Space Telescope launched in 2021.","Webb observes mainly infrared light, which allows it to see through clouds of cosmic dust."]}],"prompt":"The student wants to emphasize a difference in the kind of light the two telescopes observe. Which choice most effectively uses relevant information from the notes to accomplish this goal?","choices":["While Hubble observes mainly visible and ultraviolet light, Webb observes mainly infrared light.","Both Hubble and Webb are space telescopes launched by major space agencies.","Webb, which launched in 2021, can see through clouds of cosmic dust.","Hubble launched in 1990, more than thirty years before Webb."],"answer":{"choice":"A"},"explanation":"The goal is a contrast in the light each telescope observes. Choice A states both and contrasts them with \"While.\" Choice D gives a difference, but in launch dates rather than light."},{"id":"en-rs-03","subject":"english","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","type":"mcq","stimulus":[{"type":"list","intro":"While researching a topic, a student has taken the following notes:","items":["Octavia E. Butler (1947–2006) was an American writer of science fiction.","Her novel *Kindred* (1979) follows a Black woman who is pulled back in time to a plantation in early nineteenth-century Maryland.","In 1995, Butler became the first science fiction writer to receive a MacArthur Fellowship."]}],"prompt":"The student wants to introduce Butler to an audience unfamiliar with her. Which choice most effectively uses relevant information from the notes to accomplish this goal?","choices":["In 1995, a writer received a MacArthur Fellowship.","*Kindred* was published in 1979.","Octavia E. Butler, an American science fiction writer, was the first writer in her genre to receive a MacArthur Fellowship.","The novel *Kindred* is partly set in Maryland."],"answer":{"choice":"C"},"explanation":"An introduction should identify who Butler is and why she matters. Choice C names her, her genre, and a notable achievement. The other choices don't identify her for a new audience."},{"id":"en-rs-04","subject":"english","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","type":"mcq","stimulus":[{"type":"list","intro":"While researching a topic, a student has taken the following notes:","items":["A study compared reading comprehension on paper and on screens.","Participants read passages either in print or on a tablet.","For longer texts, participants who read on paper scored higher on comprehension questions.","For short texts, there was no significant difference between the two groups."]}],"prompt":"The student wants to present the study's findings about short texts. Which choice most effectively uses relevant information from the notes to accomplish this goal?","choices":["Participants in the study read passages either in print or on a tablet.","Readers who used paper scored higher on questions about longer texts.","The study compared reading comprehension on paper and on screens.","For short texts, the study found no significant difference in comprehension between reading on paper and reading on a tablet."],"answer":{"choice":"D"},"explanation":"Only choice D reports the finding for short texts. Choice B is a finding, but about longer texts."},{"id":"en-rs-05","subject":"english","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"medium","type":"mcq","stimulus":[{"type":"list","intro":"While researching a topic, a student has taken the following notes:","items":["Kelp forests grow in cool, nutrient-rich coastal waters.","Giant kelp can grow as much as 60 centimeters in a single day.","Sea otters eat sea urchins, which feed on kelp.","Where sea otters have disappeared, urchin populations have grown and kelp forests have declined."]}],"prompt":"The student wants to explain the role sea otters play in kelp forests. Which choice most effectively uses relevant information from the notes to accomplish this goal?","choices":["Giant kelp can grow as much as 60 centimeters in a single day.","Kelp forests grow in cool, nutrient-rich coastal waters.","By eating sea urchins, which feed on kelp, sea otters help keep kelp forests from declining.","Sea urchins feed on kelp in coastal waters."],"answer":{"choice":"C"},"explanation":"Choice C explains the otters' role: they control urchins, which protects the kelp. The other choices don't mention otters."},{"id":"en-rs-06","subject":"english","domain":"Expression of Ideas","skill":"Rhetorical Synthesis","difficulty":"hard","type":"mcq","stimulus":[{"type":"list","intro":"While researching a topic, a student has taken the following notes:","items":["Hedy Lamarr was a Hollywood film star in the 1930s and 1940s.","During World War II, she co-invented a frequency-hopping system meant to keep enemies from jamming torpedo guidance signals.","The U.S. Navy did not adopt the system during the war.","Frequency-hopping principles are now used in technologies such as Wi-Fi and Bluetooth."]}],"prompt":"The student wants to emphasize the lasting significance of Lamarr's invention. Which choice most effectively uses relevant information from the notes to accomplish this goal?","choices":["Although the Navy did not adopt it during the war, Lamarr's frequency-hopping idea anticipated principles used today in Wi-Fi and Bluetooth.","Hedy Lamarr starred in Hollywood films in the 1930s and 1940s.","The U.S. Navy did not adopt Lamarr's system during World War II.","Lamarr co-invented her frequency-hopping system during World War II."],"answer":{"choice":"A"},"explanation":"\"Lasting significance\" means impact beyond its time. Choice A links the invention to modern Wi-Fi and Bluetooth."},{"id":"ma-alg-01","subject":"math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"If $3x + 7 = 22$, what is the value of $x$?","choices":["$3$","$5$","$7$","$15$"],"answer":{"choice":"B"},"explanation":"Subtract 7 from both sides: $3x = 15$. Divide by 3: $x = 5$."},{"id":"ma-alg-02","subject":"math","domain":"Algebra","skill":"Linear equations in one variable","difficulty":"easy","type":"spr","stimulus":[],"prompt":"If $4(x - 2) = 20$, what is the value of $x$?","choices":null,"answer":{"value":7,"accepted":["7"]},"explanation":"Divide both sides by 4: $x - 2 = 5$, so $x = 7$."},{"id":"ma-alg-03","subject":"math","domain":"Algebra","skill":"Linear functions","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"A gym charges a one-time membership fee of \\$40 plus \\$25 per month. Which equation gives the total cost $C$, in dollars, of a membership for $m$ months?","choices":["$C = 40m + 25$","$C = 25m + 40$","$C = 65m$","$C = 40 + \\dfrac{m}{25}$"],"answer":{"choice":"B"},"explanation":"The monthly charge grows with $m$, so it's $25m$. The one-time fee of 40 is added once: $C = 25m + 40$."},{"id":"ma-alg-04","subject":"math","domain":"Algebra","skill":"Systems of two linear equations","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"$$2x + y = 11$$ $$x - y = 1$$"}],"prompt":"The solution to the given system of equations is $(x, y)$. What is the value of $x$?","choices":["$3$","$5$","$4$","$7$"],"answer":{"choice":"C"},"explanation":"Add the equations to eliminate $y$: $3x = 12$, so $x = 4$ (and $y = 3$)."},{"id":"ma-alg-05","subject":"math","domain":"Algebra","skill":"Linear functions","difficulty":"medium","type":"spr","stimulus":[],"prompt":"A line in the $xy$-plane passes through the points $(1, 3)$ and $(4, 12)$. What is the slope of the line?","choices":null,"answer":{"value":3,"accepted":["3"]},"explanation":"Slope $= \\dfrac{12 - 3}{4 - 1} = \\dfrac{9}{3} = 3$."},{"id":"ma-alg-06","subject":"math","domain":"Algebra","skill":"Linear inequalities","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"Which inequality represents all values of $x$ for which $5 - 2x > 11$?","choices":["$x > 3$","$x < 3$","$x > -3$","$x < -3$"],"answer":{"choice":"D"},"explanation":"Subtract 5: $-2x > 6$. Dividing by $-2$ reverses the inequality: $x < -3$."},{"id":"ma-alg-07","subject":"math","domain":"Algebra","skill":"Systems of two linear equations","difficulty":"hard","type":"spr","stimulus":[{"type":"text","text":"$$3x + ky = 8$$ $$6x + 10y = 16$$"}],"prompt":"In the given system of equations, $k$ is a constant. If the system has infinitely many solutions, what is the value of $k$?","choices":null,"answer":{"value":5,"accepted":["5"]},"explanation":"Infinitely many solutions means the equations describe the same line. The second equation is 2 times the first ($6x$ and $16$), so $2k = 10$ and $k = 5$."},{"id":"ma-alg-08","subject":"math","domain":"Algebra","skill":"Systems of two linear equations","difficulty":"hard","type":"mcq","stimulus":[{"type":"text","text":"$$y = 2x + 3$$ $$y = ax - 5$$"}],"prompt":"In the given system of equations, $a$ is a constant. If the system has no solution, what is the value of $a$?","choices":["$-5$","$-2$","$2$","$3$"],"answer":{"choice":"C"},"explanation":"A linear system has no solution when the lines are parallel and distinct: same slope, different intercepts. The slopes must both be 2, and the intercepts (3 and $-5$) already differ, so $a = 2$."},{"id":"ma-alg-09","subject":"math","domain":"Algebra","skill":"Systems of two linear equations","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"A school club bought 30 tickets to a play for a total of \\$288. Adult tickets cost \\$12 each and student tickets cost \\$8 each. How many adult tickets did the club buy?","choices":["$12$","$15$","$18$","$20$"],"answer":{"choice":"A"},"explanation":"Let $a$ be adult tickets and $s$ student tickets: $a + s = 30$ and $12a + 8s = 288$. Substitute $s = 30 - a$: $12a + 240 - 8a = 288$, so $4a = 48$ and $a = 12$."},{"id":"ma-alg-10","subject":"math","domain":"Algebra","skill":"Linear functions","difficulty":"hard","type":"spr","stimulus":[],"prompt":"For the linear function $f$, $f(2) = 7$ and $f(6) = 19$. What is the value of $f(10)$?","choices":null,"answer":{"value":31,"accepted":["31"]},"explanation":"The slope is $\\dfrac{19 - 7}{6 - 2} = 3$. From $x = 6$ to $x = 10$ the input increases by 4, so the output increases by 12: $f(10) = 19 + 12 = 31$."},{"id":"ma-alg-11","subject":"math","domain":"Algebra","skill":"Linear functions","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"The equation $y = 15x + 120$ gives the total amount $y$, in dollars, in Maya's savings account $x$ weeks after she started a savings plan. What is the best interpretation of $15$ in this context?","choices":["Maya adds \\$15 to the account each week.","Maya had \\$15 in the account when she started the plan.","Maya will have \\$15 in the account after one week.","Maya will save for 15 weeks."],"answer":{"choice":"A"},"explanation":"In $y = 15x + 120$, the coefficient of $x$ is the rate of change: each additional week adds 15 dollars. The constant 120 is the starting amount."},{"id":"ma-adv-01","subject":"math","domain":"Advanced Math","skill":"Equivalent expressions","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"Which expression is equivalent to $(x + 3)(x - 5)$?","choices":["$x^2 - 15$","$x^2 + 2x - 15$","$x^2 - 2x - 15$","$x^2 - 8x - 15$"],"answer":{"choice":"C"},"explanation":"Expand: $x^2 - 5x + 3x - 15 = x^2 - 2x - 15$."},{"id":"ma-adv-02","subject":"math","domain":"Advanced Math","skill":"Nonlinear equations in one variable","difficulty":"medium","type":"spr","stimulus":[],"prompt":"What is the sum of the solutions to the equation $x^2 - 6x + 5 = 0$?","choices":null,"answer":{"value":6,"accepted":["6"]},"explanation":"Factor: $(x - 1)(x - 5) = 0$, so $x = 1$ or $x = 5$. Their sum is $6$."},{"id":"ma-adv-03","subject":"math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"A population of 2,000 bacteria doubles every 3 hours. Which function gives the number of bacteria, $P(t)$, after $t$ hours?","choices":["$P(t) = 2{,}000(2)^{t/3}$","$P(t) = 2{,}000(2)^{3t}$","$P(t) = 2{,}000(3)^{t/2}$","$P(t) = 2{,}000 + 2\\left(\\dfrac{t}{3}\\right)$"],"answer":{"choice":"A"},"explanation":"Doubling means a growth factor of 2, applied once every 3 hours, so the exponent is $\\dfrac{t}{3}$: $P(t) = 2{,}000(2)^{t/3}$."},{"id":"ma-adv-04","subject":"math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"The function $f$ is defined by $f(x) = 3x^2 - 4$. What is the value of $f(-2)$?","choices":["$-16$","$-8$","$8$","$32$"],"answer":{"choice":"C"},"explanation":"$f(-2) = 3(-2)^2 - 4 = 3(4) - 4 = 8$."},{"id":"ma-adv-05","subject":"math","domain":"Advanced Math","skill":"Nonlinear equations in one variable","difficulty":"hard","type":"spr","stimulus":[],"prompt":"In the equation $x^2 + bx + 16 = 0$, $b$ is a positive constant. If the equation has exactly one real solution, what is the value of $b$?","choices":null,"answer":{"value":8,"accepted":["8"]},"explanation":"A quadratic has exactly one real solution when its discriminant is 0: $b^2 - 4(1)(16) = 0$, so $b^2 = 64$ and, since $b > 0$, $b = 8$."},{"id":"ma-adv-06","subject":"math","domain":"Advanced Math","skill":"Equivalent expressions","difficulty":"hard","type":"mcq","stimulus":[],"prompt":"Which expression is equivalent to $\\dfrac{x^2 - 9}{x + 3}$ for $x \\neq -3$?","choices":["$x + 3$","$x - 3$","$x - 9$","$x^2 - 3$"],"answer":{"choice":"B"},"explanation":"Factor the numerator as a difference of squares: $\\dfrac{(x + 3)(x - 3)}{x + 3} = x - 3$."},{"id":"ma-adv-07","subject":"math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"The value of a car, in dollars, $t$ years after it was purchased is modeled by $V(t) = 24{,}000(0.85)^t$. What is the best interpretation of $24{,}000$ in this context?","choices":["The value of the car one year after it was purchased","The amount by which the value decreases each year","The value of the car when it was purchased","The percent by which the value decreases each year"],"answer":{"choice":"C"},"explanation":"When $t = 0$, $V(0) = 24{,}000(0.85)^0 = 24{,}000$, so it is the car's value at purchase."},{"id":"ma-adv-08","subject":"math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"hard","type":"mcq","stimulus":[],"prompt":"The function $g$ is defined by $g(x) = (x - 4)^2 + 3$. What is the minimum value of $g(x)$?","choices":["$-4$","$4$","$7$","$3$"],"answer":{"choice":"D"},"explanation":"The vertex form $a(x - h)^2 + k$ with $a > 0$ has minimum value $k$. Since $(x - 4)^2 \\ge 0$, the smallest value is $3$, reached at $x = 4$."},{"id":"ma-adv-09","subject":"math","domain":"Advanced Math","skill":"Nonlinear equations in one variable","difficulty":"medium","type":"spr","stimulus":[],"prompt":"If $2^{x + 1} = 32$, what is the value of $x$?","choices":null,"answer":{"value":4,"accepted":["4"]},"explanation":"$32 = 2^5$, so $x + 1 = 5$ and $x = 4$."},{"id":"ma-adv-10","subject":"math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"hard","type":"mcq","stimulus":[],"prompt":"How many times does the graph of $h(x) = x^3 - 4x$ intersect the $x$-axis?","choices":["$0$","$1$","$2$","$3$"],"answer":{"choice":"D"},"explanation":"Factor: $x^3 - 4x = x(x - 2)(x + 2)$. The zeros are $-2$, $0$, and $2$, so the graph crosses the $x$-axis 3 times."},{"id":"ma-adv-11","subject":"math","domain":"Advanced Math","skill":"Nonlinear functions","difficulty":"medium","type":"spr","stimulus":[],"prompt":"The function $f$ is defined by $f(x) = \\dfrac{x^2 + 6}{2}$. What is the value of $f(4)$?","choices":null,"answer":{"value":11,"accepted":["11"]},"explanation":"$f(4) = \\dfrac{4^2 + 6}{2} = \\dfrac{22}{2} = 11$."},{"id":"ma-psd-01","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Ratios, rates, proportional relationships, and units","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"A recipe uses 3 cups of flour for every 2 cups of sugar. How many cups of flour are needed if 10 cups of sugar are used?","choices":["$6$","$13$","$15$","$20$"],"answer":{"choice":"C"},"explanation":"10 cups of sugar is 5 times 2 cups, so use $5 \\times 3 = 15$ cups of flour."},{"id":"ma-psd-02","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Percentages","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"A jacket originally priced at \\$80 is on sale for 25% off. What is the sale price of the jacket?","choices":["\\$20","\\$60","\\$55","\\$75"],"answer":{"choice":"B"},"explanation":"25% of 80 is 20, so the sale price is $80 - 20 = 60$ dollars."},{"id":"ma-psd-03","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Two-variable data: models and scatterplots","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"The scatterplot shows the relationship between two variables, $x$ and $y$. A line of best fit for the data is also shown."},{"type":"figure","figure":{"kind":"scatter","xLabel":"x","yLabel":"y","x":[0,10,1],"y":[0,14,2],"points":[[1,2.5],[2,4.6],[3,4.8],[4,6.6],[5,6.3],[6,8.7],[7,8.8],[8,10.4],[9,11.3],[10,11.5]],"line":[[0,2],[10,12]]}}],"prompt":"At $x = 8$, which of the following is closest to the $y$-value predicted by the line of best fit?","choices":["$8$","$9$","$10$","$12$"],"answer":{"choice":"C"},"explanation":"The line passes through $(0, 2)$ and $(10, 12)$, so its equation is $y = x + 2$. At $x = 8$, the predicted value is $10$."},{"id":"ma-psd-04","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"One-variable data: distributions and measures of center","difficulty":"medium","type":"spr","stimulus":[],"prompt":"The mean of five numbers is 12. Four of the numbers are 8, 10, 14, and 15. What is the fifth number?","choices":null,"answer":{"value":13,"accepted":["13"]},"explanation":"The five numbers sum to $5 \\times 12 = 60$. The four known numbers sum to 47, so the fifth is $60 - 47 = 13$."},{"id":"ma-psd-05","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"One-variable data: distributions and measures of center","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"What is the median of the data set $3, 7, 7, 9, 12, 15$?","choices":["$7$","$8$","$8.5$","$9$"],"answer":{"choice":"B"},"explanation":"With six values, the median is the mean of the 3rd and 4th values: $\\dfrac{7 + 9}{2} = 8$."},{"id":"ma-psd-06","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Probability and conditional probability","difficulty":"hard","type":"mcq","stimulus":[{"type":"table","title":"Club Membership by Grade","headers":["","Robotics","Drama","Total"],"rows":[["Grade 10","18","12","30"],["Grade 11","14","16","30"],["Total","32","28","60"]]}],"prompt":"The table shows the number of students in two clubs, by grade. Each student is in exactly one club. If a student is selected at random from the drama club, what is the probability that the student is in grade 11?","choices":["$\\dfrac{4}{15}$","$\\dfrac{8}{15}$","$\\dfrac{4}{7}$","$\\dfrac{7}{15}$"],"answer":{"choice":"C"},"explanation":"Restrict to the drama club: 28 students, 16 of whom are in grade 11. The probability is $\\dfrac{16}{28} = \\dfrac{4}{7}$."},{"id":"ma-psd-07","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Percentages","difficulty":"medium","type":"spr","stimulus":[],"prompt":"The price of a book increased from \\$50 to \\$65. By what percent did the price increase?","choices":null,"answer":{"value":30,"accepted":["30"]},"explanation":"The increase is 15, and $\\dfrac{15}{50} = 0.30$, or 30%. Enter 30 (without the percent sign)."},{"id":"ma-psd-08","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Ratios, rates, proportional relationships, and units","difficulty":"hard","type":"spr","stimulus":[],"prompt":"A train travels at a constant speed of 72 kilometers per hour. What is this speed in meters per second?","choices":null,"answer":{"value":20,"accepted":["20"]},"explanation":"$72 \\text{ km/h} = \\dfrac{72{,}000 \\text{ m}}{3{,}600 \\text{ s}} = 20$ meters per second."},{"id":"ma-psd-09","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Two-variable data: models and scatterplots","difficulty":"medium","type":"mcq","stimulus":[{"type":"text","text":"The line graph shows the temperature in a city, in degrees Celsius, recorded every two hours from 6:00 a.m. to 6:00 p.m."},{"type":"figure","figure":{"kind":"line","xLabel":"Hour of the day","yLabel":"Temperature (°C)","x":[6,18,2],"y":[10,26,2],"points":[[6,12],[8,14],[10,19],[12,22],[14,23],[16,21],[18,17]]}}],"prompt":"During which two-hour interval did the temperature increase the most?","choices":["6:00 a.m. to 8:00 a.m.","8:00 a.m. to 10:00 a.m.","10:00 a.m. to 12:00 p.m.","12:00 p.m. to 2:00 p.m."],"answer":{"choice":"B"},"explanation":"The increases are 2°, 5°, 3°, and 1° for the four intervals. The largest, 5°, occurs from 8:00 to 10:00 a.m."},{"id":"ma-psd-10","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Inference from sample statistics","difficulty":"hard","type":"mcq","stimulus":[],"prompt":"A town has 12,000 residents. In a random sample of 200 residents, 46 said they prefer a proposed park design. Based on the sample, which is the best estimate of the number of residents who prefer the design?","choices":["$230$","$2{,}760$","$460$","$5{,}520$"],"answer":{"choice":"B"},"explanation":"The sample proportion is $\\dfrac{46}{200} = 0.23$. Applied to the town: $0.23 \\times 12{,}000 = 2{,}760$."},{"id":"ma-psd-11","subject":"math","domain":"Problem-Solving and Data Analysis","skill":"Percentages","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"In a survey of 250 students, 40% said they walk to school. How many of the students surveyed said they walk to school?","choices":["$40$","$60$","$100$","$150$"],"answer":{"choice":"C"},"explanation":"$0.40 \\times 250 = 100$."},{"id":"ma-geo-01","subject":"math","domain":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"A rectangle has a length of 12 and a width of 5. What is the length of a diagonal of the rectangle?","choices":["$7$","$13$","$17$","$60$"],"answer":{"choice":"B"},"explanation":"The diagonal is the hypotenuse of a right triangle with legs 12 and 5: $\\sqrt{12^2 + 5^2} = \\sqrt{169} = 13$."},{"id":"ma-geo-02","subject":"math","domain":"Geometry and Trigonometry","skill":"Lines, angles, and triangles","difficulty":"easy","type":"mcq","stimulus":[],"prompt":"A person who is 6 feet tall casts a shadow 4 feet long. At the same time, a nearby flagpole casts a shadow 14 feet long. How tall, in feet, is the flagpole?","choices":["$9$","$16$","$21$","$24$"],"answer":{"choice":"C"},"explanation":"The triangles formed are similar, so heights and shadows are proportional: $\\dfrac{6}{4} = \\dfrac{h}{14}$, which gives $h = 21$."},{"id":"ma-geo-03","subject":"math","domain":"Geometry and Trigonometry","skill":"Lines, angles, and triangles","difficulty":"medium","type":"spr","stimulus":[{"type":"figure","figure":{"kind":"svg","svg":"<svg viewBox=\"0 0 300 200\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"'Noto Serif', Georgia, serif\" font-size=\"16\">\n  <polygon points=\"30,170 270,170 120,35\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/>\n  <text x=\"52\" y=\"162\">50°</text>\n  <text x=\"222\" y=\"162\">65°</text>\n  <text x=\"112\" y=\"68\" font-style=\"italic\">x°</text>\n  <text x=\"14\" y=\"188\">A</text>\n  <text x=\"276\" y=\"188\">B</text>\n  <text x=\"114\" y=\"26\">C</text>\n</svg>","width":300,"height":200},"caption":"Note: Figure not drawn to scale."}],"prompt":"In triangle $ABC$ shown, what is the value of $x$?","choices":null,"answer":{"value":65,"accepted":["65"]},"explanation":"The angles of a triangle sum to 180°: $x = 180 - 50 - 65 = 65$."},{"id":"ma-geo-04","subject":"math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"A circle has a circumference of $10\\pi$. What is the area of the circle?","choices":["$5\\pi$","$10\\pi$","$25\\pi$","$100\\pi$"],"answer":{"choice":"C"},"explanation":"$C = 2\\pi r = 10\\pi$ gives $r = 5$, so the area is $\\pi r^2 = 25\\pi$."},{"id":"ma-geo-05","subject":"math","domain":"Geometry and Trigonometry","skill":"Lines, angles, and triangles","difficulty":"medium","type":"spr","stimulus":[],"prompt":"Two parallel lines are intersected by a transversal. One of the angles formed measures 118°. What is the measure, in degrees, of each acute angle formed?","choices":null,"answer":{"value":62,"accepted":["62"]},"explanation":"Every angle formed is either congruent or supplementary to the 118° angle. The acute angles measure $180 - 118 = 62$ degrees."},{"id":"ma-geo-06","subject":"math","domain":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"hard","type":"mcq","stimulus":[],"prompt":"In right triangle $ABC$, angle $C$ is the right angle and $\\sin A = \\dfrac{5}{13}$. What is the value of $\\cos B$?","choices":["$\\dfrac{5}{13}$","$\\dfrac{12}{13}$","$\\dfrac{13}{5}$","$\\dfrac{5}{12}$"],"answer":{"choice":"A"},"explanation":"Angles $A$ and $B$ are complementary, and the sine of an angle equals the cosine of its complement, so $\\cos B = \\sin A = \\dfrac{5}{13}$."},{"id":"ma-geo-07","subject":"math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"hard","type":"spr","stimulus":[],"prompt":"The equation $x^2 + y^2 - 6x + 4y - 12 = 0$ defines a circle in the $xy$-plane. What is the radius of the circle?","choices":null,"answer":{"value":5,"accepted":["5"]},"explanation":"Complete the square: $(x - 3)^2 + (y + 2)^2 = 12 + 9 + 4 = 25$. The radius is $\\sqrt{25} = 5$."},{"id":"ma-geo-08","subject":"math","domain":"Geometry and Trigonometry","skill":"Area and volume","difficulty":"medium","type":"mcq","stimulus":[],"prompt":"A right circular cylinder has a radius of 3 and a height of 8. What is the volume of the cylinder?","choices":["$24\\pi$","$72\\pi$","$48\\pi$","$144\\pi$"],"answer":{"choice":"B"},"explanation":"$V = \\pi r^2 h = \\pi(3)^2(8) = 72\\pi$."},{"id":"ma-geo-09","subject":"math","domain":"Geometry and Trigonometry","skill":"Circles","difficulty":"hard","type":"mcq","stimulus":[],"prompt":"A circle has a radius of 9. A central angle of the circle measures $\\dfrac{2\\pi}{3}$ radians. What is the length of the arc intercepted by the angle?","choices":["$3\\pi$","$9\\pi$","$12\\pi$","$6\\pi$"],"answer":{"choice":"D"},"explanation":"Arc length $= r\\theta = 9 \\cdot \\dfrac{2\\pi}{3} = 6\\pi$."},{"id":"ma-geo-10","subject":"math","domain":"Geometry and Trigonometry","skill":"Right triangles and trigonometry","difficulty":"medium","type":"spr","stimulus":[],"prompt":"The hypotenuse of a $45^\\circ$-$45^\\circ$-$90^\\circ$ triangle has length $8\\sqrt{2}$. What is the length of one leg of the triangle?","choices":null,"answer":{"value":8,"accepted":["8"]},"explanation":"In a 45-45-90 triangle, the hypotenuse is $s\\sqrt{2}$, where $s$ is a leg. So $s = 8$."},{"id":"ma-geo-11","subject":"math","domain":"Geometry and Trigonometry","skill":"Area and volume","difficulty":"hard","type":"spr","stimulus":[],"prompt":"A square is inscribed in a circle with a radius of 5. What is the area of the square?","choices":null,"answer":{"value":50,"accepted":["50"]},"explanation":"The diagonal of the inscribed square is a diameter of the circle, 10. A square with diagonal $d$ has area $\\dfrac{d^2}{2} = \\dfrac{100}{2} = 50$."}]$seed$::jsonb) as q(
  id text, subject public.subject, domain text, skill text, difficulty public.difficulty,
  type public.question_type, stimulus jsonb, prompt text, choices jsonb, answer jsonb, explanation text
)
on conflict (id) do update set
  subject = excluded.subject, domain = excluded.domain, skill = excluded.skill,
  difficulty = excluded.difficulty, type = excluded.type, stimulus = excluded.stimulus,
  prompt = excluded.prompt, choices = excluded.choices, answer = excluded.answer,
  explanation = excluded.explanation;

insert into public.test_forms (id, section, title, description, modules, sort)
select id, section, title, description, modules, sort
from jsonb_to_recordset($seed$[{"id":"math-1","section":"math","title":"Math Practice Test 1","description":"Two 35-minute modules covering algebra, advanced math, data analysis and geometry.","sort":1,"modules":[{"title":"Math","subject":"math","duration_seconds":2100,"break_seconds":0,"question_ids":["ma-alg-01","ma-adv-04","ma-psd-01","ma-psd-11","ma-geo-02","ma-adv-01","ma-alg-03","ma-alg-05","ma-alg-11","ma-adv-03","ma-adv-09","ma-psd-03","ma-psd-05","ma-psd-09","ma-geo-03","ma-geo-04","ma-geo-08","ma-alg-07","ma-adv-06","ma-psd-06","ma-geo-06","ma-psd-10"]},{"title":"Math","subject":"math","duration_seconds":2100,"break_seconds":0,"question_ids":["ma-alg-02","ma-psd-02","ma-geo-01","ma-alg-04","ma-alg-06","ma-alg-09","ma-adv-02","ma-adv-07","ma-adv-11","ma-psd-04","ma-psd-07","ma-geo-05","ma-geo-10","ma-alg-08","ma-alg-10","ma-adv-05","ma-adv-08","ma-adv-10","ma-psd-08","ma-geo-07","ma-geo-09","ma-geo-11"]}]},{"id":"english-1","section":"english","title":"Reading and Writing Practice Test 1","description":"Two 32-minute modules covering vocabulary, evidence, grammar, transitions and rhetoric.","sort":2,"modules":[{"title":"Reading and Writing","subject":"english","duration_seconds":1920,"break_seconds":0,"question_ids":["en-wic-01","en-wic-02","en-wic-06","en-wic-04","en-tsp-02","en-tsp-03","en-ctc-02","en-cid-01","en-cid-02","en-coe-01","en-coe-03","en-coq-01","en-inf-03","en-inf-01","en-bnd-01","en-bnd-02","en-bnd-03","en-bnd-06","en-fss-01","en-fss-02","en-fss-05","en-trn-01","en-trn-02","en-trn-03","en-rs-01","en-rs-03","en-rs-05"]},{"title":"Reading and Writing","subject":"english","duration_seconds":1920,"break_seconds":0,"question_ids":["en-wic-03","en-wic-05","en-wic-07","en-tsp-01","en-tsp-05","en-tsp-04","en-ctc-01","en-cid-04","en-cid-03","en-coe-02","en-coq-03","en-coq-02","en-inf-02","en-inf-04","en-fss-07","en-fss-03","en-bnd-04","en-bnd-05","en-fss-04","en-fss-06","en-trn-05","en-trn-07","en-trn-04","en-trn-06","en-rs-02","en-rs-04","en-rs-06"]}]},{"id":"general-1","section":"general","title":"Full-Length Practice Test 1","description":"The complete digital SAT: Reading and Writing, a 10-minute break, then Math — scored 400–1600.","sort":3,"modules":[{"title":"Reading and Writing","subject":"english","duration_seconds":1920,"break_seconds":0,"question_ids":["en-wic-01","en-wic-02","en-wic-06","en-wic-04","en-tsp-02","en-tsp-03","en-ctc-02","en-cid-01","en-cid-02","en-coe-01","en-coe-03","en-coq-01","en-inf-03","en-inf-01","en-bnd-01","en-bnd-02","en-bnd-03","en-bnd-06","en-fss-01","en-fss-02","en-fss-05","en-trn-01","en-trn-02","en-trn-03","en-rs-01","en-rs-03","en-rs-05"]},{"title":"Reading and Writing","subject":"english","duration_seconds":1920,"break_seconds":0,"question_ids":["en-wic-03","en-wic-05","en-wic-07","en-tsp-01","en-tsp-05","en-tsp-04","en-ctc-01","en-cid-04","en-cid-03","en-coe-02","en-coq-03","en-coq-02","en-inf-02","en-inf-04","en-fss-07","en-fss-03","en-bnd-04","en-bnd-05","en-fss-04","en-fss-06","en-trn-05","en-trn-07","en-trn-04","en-trn-06","en-rs-02","en-rs-04","en-rs-06"]},{"title":"Math","subject":"math","duration_seconds":2100,"break_seconds":600,"question_ids":["ma-alg-01","ma-adv-04","ma-psd-01","ma-psd-11","ma-geo-02","ma-adv-01","ma-alg-03","ma-alg-05","ma-alg-11","ma-adv-03","ma-adv-09","ma-psd-03","ma-psd-05","ma-psd-09","ma-geo-03","ma-geo-04","ma-geo-08","ma-alg-07","ma-adv-06","ma-psd-06","ma-geo-06","ma-psd-10"]},{"title":"Math","subject":"math","duration_seconds":2100,"break_seconds":0,"question_ids":["ma-alg-02","ma-psd-02","ma-geo-01","ma-alg-04","ma-alg-06","ma-alg-09","ma-adv-02","ma-adv-07","ma-adv-11","ma-psd-04","ma-psd-07","ma-geo-05","ma-geo-10","ma-alg-08","ma-alg-10","ma-adv-05","ma-adv-08","ma-adv-10","ma-psd-08","ma-geo-07","ma-geo-09","ma-geo-11"]}]}]$seed$::jsonb) as f(
  id text, section public.exam_section, title text, description text, modules jsonb, sort int
)
on conflict (id) do update set
  section = excluded.section, title = excluded.title, description = excluded.description,
